-- Lost & Found schema (PostgreSQL) - FIRST-TIME SETUP
-- Run once on a brand-new, empty database.
-- IDs are UUID strings generated by the app (VARCHAR(36)).

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------
-- Tables (dependency order: referenced tables come first)
-- ---------------------------------------------------------------

CREATE TABLE users (
                       id                     VARCHAR(36)  PRIMARY KEY,
                       first_name             VARCHAR(255) NOT NULL,
                       last_name              VARCHAR(255) NOT NULL,
                       student_id             VARCHAR(20)  UNIQUE,              -- NULL allowed (staff)
                       email                  VARCHAR(255) NOT NULL UNIQUE,
                       phone_num              VARCHAR(255) NOT NULL UNIQUE,
                       password               VARCHAR(255) NOT NULL,
                       role                   VARCHAR(20)  NOT NULL CHECK (role IN ('Student','Moderator','Admin')),
                       email_verified         BOOLEAN      NOT NULL DEFAULT FALSE,
                       failed_login_attempts  INTEGER      NOT NULL DEFAULT 0,
                       locked_until           TIMESTAMPTZ,
                       created_at             TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE categories (
                            id    VARCHAR(36)  PRIMARY KEY,
                            name  VARCHAR(255) NOT NULL UNIQUE,
                            icon  VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX ux_categories_name_lower ON categories (lower(name));

CREATE TABLE drop_locations (
                                id           VARCHAR(36)  PRIMARY KEY,
                                name         VARCHAR(255) NOT NULL,
                                contact      VARCHAR(255) NOT NULL,
                                person_name  VARCHAR(255)
);
CREATE UNIQUE INDEX ux_drop_locations_name_lower ON drop_locations (lower(name));

-- Stores picture bytes (must exist before item_images / claims)
CREATE TABLE images (
                        id            VARCHAR(36)  PRIMARY KEY,
                        content_type  VARCHAR(50)  NOT NULL,
                        size_bytes    BIGINT       NOT NULL,
                        purpose       VARCHAR(10)  NOT NULL CHECK (purpose IN ('ITEM','PROOF','LOST_ITEM')),
                        data          BYTEA        NOT NULL,
                        created_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE items (
                       id                   VARCHAR(36)  PRIMARY KEY,
                       reporter_id          VARCHAR(36)  REFERENCES users(id),
                       name                 VARCHAR(255) NOT NULL,
                       type                 VARCHAR(10)  NOT NULL CHECK (type IN ('LOST','FOUND')),
                       description          TEXT         NOT NULL,
                       category_id          VARCHAR(36)  REFERENCES categories(id),
                       color                VARCHAR(255) NOT NULL,
                       brand                VARCHAR(255) NOT NULL,
                       distinguishing_marks TEXT         NOT NULL,   -- never exposed publicly
                       location_name        VARCHAR(255) NOT NULL,
                       drop_location_id     VARCHAR(36)  REFERENCES drop_locations(id),
                       date_occurred        DATE,
                       status               VARCHAR(10)  NOT NULL DEFAULT 'OPEN'
                           CHECK (status IN ('OPEN','MATCHED','CLAIMED','CLOSED','EXPIRED')),
                       created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
                       updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- full-text search: name (weight A) + description (weight B)
                       search_vector        TSVECTOR GENERATED ALWAYS AS (
                           setweight(to_tsvector('english', coalesce(name, '')), 'A') ||
                           setweight(to_tsvector('english', coalesce(description, '')), 'B')
                           ) STORED
);

CREATE TABLE item_images (
                             item_id   VARCHAR(36) NOT NULL REFERENCES items(id) ON DELETE CASCADE,
                             image_id  VARCHAR(36) REFERENCES images(id),
                             position  INTEGER     NOT NULL
);

CREATE TABLE claims (
                        id                 VARCHAR(36) PRIMARY KEY,
                        item_id            VARCHAR(36) REFERENCES items(id) ON DELETE CASCADE,
                        claimant_id        VARCHAR(36) REFERENCES users(id),
                        proof_description  TEXT        NOT NULL,
                        proof_image_id     VARCHAR(36) REFERENCES images(id),
                        status             VARCHAR(10) NOT NULL DEFAULT 'PENDING'
                            CHECK (status IN ('PENDING','APPROVED','REJECTED','CANCELLED')),
                        review_note        TEXT,
                        reviewed_at        TIMESTAMPTZ,
                        reviewed_by        VARCHAR(36) REFERENCES users(id),
                        created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE matches (
                         id             VARCHAR(36) PRIMARY KEY,
                         lost_item_id   VARCHAR(36) REFERENCES items(id) ON DELETE CASCADE,
                         found_item_id  VARCHAR(36) REFERENCES items(id) ON DELETE CASCADE,
                         score          DOUBLE PRECISION NOT NULL,
                         status         VARCHAR(10) NOT NULL DEFAULT 'SUGGESTED'
                             CHECK (status IN ('SUGGESTED','CONFIRMED','DISMISSED')),
                         created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE notifications (
                               id          VARCHAR(36) PRIMARY KEY,
                               user_id     VARCHAR(36) REFERENCES users(id),
                               type        VARCHAR(20) CHECK (type IN ('MATCH_FOUND','CLAIM_UPDATE')),
                               payload     JSONB,                       -- e.g. {"itemId": "...", "matchId": "..."}
                               is_read     BOOLEAN     NOT NULL DEFAULT FALSE,
                               created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- One row per issued refresh token (id = the JWT "jti"). Revoking a row logs that session out.
-- family_id groups a chain of rotated tokens: reusing an old one revokes the whole family.
CREATE TABLE refresh_tokens (
                                id          VARCHAR(36)  PRIMARY KEY,
                                user_id     VARCHAR(36)  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                                family_id   VARCHAR(36)  NOT NULL,
                                expires_at  TIMESTAMPTZ  NOT NULL,
                                revoked_at  TIMESTAMPTZ,
                                created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- One-time tokens sent by email (verify email, reset password). Only a SHA-256 hash is stored.
CREATE TABLE auth_tokens (
                             id          VARCHAR(36)  PRIMARY KEY,
                             user_id     VARCHAR(36)  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                             type        VARCHAR(20)  NOT NULL CHECK (type IN ('VERIFY_EMAIL','RESET_PASSWORD')),
                             token_hash  VARCHAR(64)  NOT NULL UNIQUE,
                             expires_at  TIMESTAMPTZ  NOT NULL,
                             used_at     TIMESTAMPTZ,
                             created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------
CREATE INDEX ix_items_reporter       ON items (reporter_id);
CREATE INDEX ix_items_type           ON items (type);
CREATE INDEX ix_items_category       ON items (category_id);
CREATE INDEX ix_items_drop_location  ON items (drop_location_id);
CREATE INDEX ix_items_status_created ON items (status, created_at DESC);
CREATE INDEX ix_items_search         ON items USING GIN (search_vector);
CREATE INDEX ix_items_name_trgm      ON items USING GIN (name gin_trgm_ops);

CREATE INDEX ix_item_images_item     ON item_images (item_id);
CREATE INDEX ix_item_images_image    ON item_images (image_id);

CREATE INDEX ix_claims_item          ON claims (item_id);
CREATE INDEX ix_claims_claimant      ON claims (claimant_id, created_at DESC);
CREATE INDEX ix_claims_proof_image   ON claims (proof_image_id);
CREATE UNIQUE INDEX ux_claims_one_pending
    ON claims (item_id, claimant_id) WHERE status = 'PENDING';

CREATE INDEX ix_matches_lost         ON matches (lost_item_id);
CREATE INDEX ix_matches_found        ON matches (found_item_id);
CREATE UNIQUE INDEX ux_matches_pair  ON matches (lost_item_id, found_item_id);

CREATE INDEX ix_notifications_user   ON notifications (user_id);

CREATE INDEX ix_refresh_tokens_user    ON refresh_tokens (user_id);
CREATE INDEX ix_refresh_tokens_family  ON refresh_tokens (family_id);
CREATE INDEX ix_refresh_tokens_expires ON refresh_tokens (expires_at);

CREATE INDEX ix_auth_tokens_user    ON auth_tokens (user_id, type);
CREATE INDEX ix_auth_tokens_expires ON auth_tokens (expires_at);